2	create table public.import_row_decisions (
3	  id uuid primary key default gen_random_uuid(),
4	  workspace_id uuid not null references public.workspaces(id) on delete cascade,
5	  source_id uuid not null references public.source_transactions(id) on delete cascade,
6	  action text not null check(action in ('accepted','rejected')),
7	  source_record jsonb not null,
8	  transaction_record jsonb,
9	  balance_records jsonb not null default '[]',
10	  actor_id uuid references auth.users(id) on delete set null,
11	  created_at timestamptz not null default clock_timestamp(),
12	  undone_at timestamptz,
13	  undone_by uuid references auth.users(id) on delete set null
14	);
15	create unique index import_row_decisions_active on public.import_row_decisions(source_id) where undone_at is null;
16	create index import_row_decisions_workspace on public.import_row_decisions(workspace_id,source_id);
17	alter table public.import_row_decisions enable row level security;
18	create policy import_row_decisions_read on public.import_row_decisions for select to authenticated using(public.owns_workspace(workspace_id));
19	revoke all on public.import_row_decisions from public,anon,authenticated;
20	grant select on public.import_row_decisions to authenticated;
