36	create function public.undo_import_row_decision(p_decision_id uuid) returns public.source_transactions
37	language plpgsql security definer set search_path='' as $$
38	declare decision public.import_row_decisions%rowtype; source public.source_transactions%rowtype;
39	  imported public.imports%rowtype; target_id uuid; transaction_record jsonb; balances jsonb;
40	begin
41	  if auth.uid() is null then raise exception 'Authentication required' using errcode='28000'; end if;
42	  select * into decision from public.import_row_decisions where id=p_decision_id and public.owns_workspace(workspace_id);
43	  if not found then raise exception 'Review history not found' using errcode='P0002'; end if;
44	  select * into strict source from public.source_transactions where id=decision.source_id;
45	  target_id:=(decision.transaction_record->>'id')::uuid;
46	  -- Match the canonical-before-import-before-source order used by acceptance.
47	  perform id from public.transactions where id=target_id for update;
48	  select * into strict imported from public.imports where id=source.import_id for update;
49	  select * into strict source from public.source_transactions where id=decision.source_id for update;
50	  select * into strict decision from public.import_row_decisions where id=p_decision_id for update;
51	  if imported.status<>'completed' then raise exception 'Import is not completed' using errcode='PT409'; end if;
52	  if decision.undone_at is not null then
53	    if source.status='review' then return source; end if;
54	    raise exception 'Review decision changed; refresh and retry' using errcode='PT409';
55	  end if;
56	  if source.status is distinct from decision.action or to_jsonb(source) is distinct from decision.source_record then
57	    raise exception 'Review decision changed; refresh and retry' using errcode='PT409';
58	  end if;
59	  if 'excluded_by_review'=any(source.review_reasons) then raise exception 'Excluded source observation cannot be reopened' using errcode='22023'; end if;
60	  if decision.action='accepted' then
61	    select to_jsonb(t) into transaction_record from public.transactions t where t.id=target_id and t.workspace_id=decision.workspace_id;
62	    if transaction_record is null or transaction_record is distinct from decision.transaction_record then
63	      raise exception 'Undo later transaction changes before reopening this row' using errcode='PT409';
64	    end if;
65	    if exists(select 1 from public.correction_events where transaction_id=target_id)
66	      or exists(select 1 from public.recurring_series_transactions where transaction_id=target_id)
67	      or exists(select 1 from public.recurring_occurrence_settlements where transaction_id=target_id and undone_at is null)
68	      or exists(select 1 from public.transaction_split_sets where transaction_id=target_id)
69	      or exists(select 1 from public.transaction_links where primary_transaction_id=target_id or counterpart_transaction_id=target_id)
70	      or exists(select 1 from public.transaction_link_fees where transaction_id=target_id)
71	      or exists(select 1 from public.pending_hold_resolutions where undone_at is null and (pending_transaction_id=target_id or posted_transaction_id=target_id))
72	      or exists(select 1 from public.transactions t where (t.id=target_id and (t.transfer_id is not null or t.refund_of_id is not null)) or t.refund_of_id=target_id or t.transfer_id=target_id) then
73	      raise exception 'Undo dependent corrections, recurring matches, links or pending resolutions before reopening this row' using errcode='PT409';
74	    end if;
75	    if not exists(select 1 from public.transaction_sources l where l.transaction_id=target_id and l.source_transaction_id=source.id)
76	      or exists(select 1 from public.transaction_sources l where l.transaction_id=target_id and l.source_transaction_id<>source.id) then
77	      raise exception 'This transaction has other source evidence; open Transactions to review it' using errcode='PT409';
78	    end if;
79	    if exists(select 1 from public.balance_snapshots b where b.workspace_id=decision.workspace_id and b.undone_at is null
80	      and exists(select 1 from jsonb_array_elements(coalesce(b.covered_transactions,'[]'::jsonb)) covered where covered->>'id'=target_id::text)) then
81	      raise exception 'Undo dependent reviewed balances in Accounts before reopening this row' using errcode='PT409';
82	    end if;
83	    perform id from public.balance_snapshots where source_transaction_id=source.id order by id for update;
84	    select coalesce(jsonb_agg(to_jsonb(b) order by b.id),'[]'::jsonb) into balances from public.balance_snapshots b where b.source_transaction_id=source.id;
85	    if balances is distinct from decision.balance_records then raise exception 'Balance evidence changed; review it in Accounts first' using errcode='PT409'; end if;
86	    delete from public.balance_snapshots where source_transaction_id=source.id;
87	    delete from public.transaction_sources l where l.transaction_id=target_id and l.source_transaction_id=source.id;
88	    delete from public.transactions where id=target_id;
89	  end if;
90	  update public.import_row_decisions set undone_at=clock_timestamp(),undone_by=auth.uid() where id=decision.id;
91	  update public.source_transactions set status='review',normalized_row=normalized_row-'resolution' where id=source.id returning * into source;
92	  perform public.recount_import_progress(imported.id);
93	  return source;
94	end;
95	$$;
96	revoke all on function public.undo_import_row_decision(uuid) from public,anon;
97	grant execute on function public.undo_import_row_decision(uuid) to authenticated;
