113	revoke all on function public.undo_transaction_correction(uuid, integer) from public;
114	grant execute on function public.correct_transaction(uuid, integer, text, text) to authenticated;
115	grant execute on function public.undo_transaction_correction(uuid, integer) to authenticated;
