3	create function public.guard_financial_source_delete() returns trigger language plpgsql security definer set search_path='' as $$
4	begin
5	  if old.transfer_id is not null or old.refund_of_id is not null
6	    or exists(select 1 from public.transactions where transfer_id=old.id or refund_of_id=old.id)
7	    or exists(select 1 from public.transaction_sources where transaction_id=old.id)
8	    or exists(select 1 from public.correction_events where transaction_id=old.id)
