10	    or exists(select 1 from public.transaction_split_sets where transaction_id=old.id)
11	    or exists(select 1 from public.transaction_links where primary_transaction_id=old.id or counterpart_transaction_id=old.id)
12	    then raise exception 'Linked, corrected or source-backed financial evidence must be retained; undo the relevant change instead' using errcode='22023'; end if;
13	  return old;
14	end;
15	$$;
16	revoke all on function public.guard_financial_source_delete() from public,anon,authenticated;
