18	export function groupedByDescription<T extends { row: { description: string; posted_on: string } }>(items: T[]) {
19	  const groups = new Map<string, T[]>();
20	  for (const item of items) { const key = item.row.description.trim().toLocaleLowerCase("en"); groups.set(key, [...(groups.get(key) ?? []), item]); }
21	  return [...groups.values()].map(group => [...group].sort((a, b) => b.row.posted_on.localeCompare(a.row.posted_on)));
22	}
