3	import { useEffect, useId, useState } from "react";
4	import { supportedCurrencies } from "@/lib/finance/fx";
5	
6	const COMMON = ["EUR", "USD", "GBP", "CHF", "JPY", "CAD", "AUD", "SEK", "NOK", "DKK", "PLN", "INR", "CNY"];
7	const field = "min-h-10 w-full rounded-[10px] border border-input bg-card px-3 py-2 text-sm text-foreground outline-none focus:border-brand focus:ring-2 focus:ring-brand/15";
8	
9	export type CurrencyOption = { code: string; name: string; label: string };
10	
11	/** Every currency the server accepts, the usual ones first, named in the viewer's language. */
12	export function currencyOptions(locale = "en"): CurrencyOption[] {
13	  const names = new Intl.DisplayNames([locale], { type: "currency" });
14	  const codes = [...COMMON, ...supportedCurrencies().filter(code => !COMMON.includes(code))];
15	  return codes.map(code => { const name = names.of(code) ?? code; return { code, name, label: name === code ? code : `${code} · ${name}` }; });
16	}
17	
18	/** Finds by code or by any part of the name; codes that start with the text come first. */
19	export function matchCurrencies(options: CurrencyOption[], text: string) {
20	  const query = text.trim().toLowerCase();
21	  if (!query) return options;
22	  const byCode = options.filter(option => option.code.toLowerCase().startsWith(query));
23	  return [...byCode, ...options.filter(option => !byCode.includes(option) && option.label.toLowerCase().includes(query))];
24	}
25	
26	/** The code a form submits for what is typed: a chosen option's code, or the text itself so the server can refuse it. */
27	export function currencyCode(options: CurrencyOption[], text: string) {
28	  return options.find(option => option.label === text)?.code ?? text.trim().toUpperCase();
29	}
30	
31	/** A searchable currency picker that shows code and name and submits the three-letter code under `name`. */
32	export function CurrencySelect({ name, label, defaultValue = "", locale, onChange, className = "" }: {
33	  name: string; label: string; defaultValue?: string; locale?: string; onChange?: (code: string) => void; className?: string;
34	}) {
35	  const id = useId();
36	  const [options] = useState(() => currencyOptions(locale));
37	  const known = (code: string) => options.find(option => option.code === code);
38	  const [text, setText] = useState(known(defaultValue)?.label ?? defaultValue);
39	  const [open, setOpen] = useState(false);
40	  const [active, setActive] = useState(-1);
41	  const code = currencyCode(options, text);
42	  // A chosen option lists everything again, so changing your mind does not start with clearing the field.
43	  const shown = open ? (options.some(option => option.label === text) ? options : matchCurrencies(options, text)) : [];
44	  useEffect(() => { if (active >= 0) document.getElementById(`${id}-${active}`)?.scrollIntoView({ block: "nearest" }); }, [active, id]);
45	  const type = (next: string) => { setText(next); setOpen(true); setActive(-1); onChange?.(currencyCode(options, next)); };
46	  const choose = (option: CurrencyOption) => { setText(option.label); setOpen(false); setActive(-1); onChange?.(option.code); };
47	  return <span className={`relative block w-56 max-w-full ${className}`}>
48	    <input type="hidden" name={name} value={code} />
49	    <input role="combobox" aria-label={label} aria-expanded={shown.length > 0} aria-controls={`${id}-list`} aria-autocomplete="list" aria-activedescendant={active >= 0 ? `${id}-${active}` : undefined}
50	      autoComplete="off" required value={text} className={field} suppressHydrationWarning
51	      onChange={event => type(event.target.value)}
52	      onFocus={event => { event.target.select(); setOpen(true); }}
53	      onBlur={() => { const match = known(code); if (match) setText(match.label); setOpen(false); setActive(-1); }}
54	      onKeyDown={event => {
55	        if (event.key === "Escape") setOpen(false);
56	        if (event.key === "ArrowDown" || event.key === "ArrowUp") {
57	          event.preventDefault(); setOpen(true);
58	          const step = event.key === "ArrowDown" ? 1 : -1;
59	          if (shown.length) setActive(current => Math.max(0, Math.min(shown.length - 1, current + step)));
60	        }
61	        if (event.key === "Enter" && shown[active]) { event.preventDefault(); choose(shown[active]); }
62	      }} />
63	    <ul id={`${id}-list`} role="listbox" aria-label={label} hidden={!shown.length} className="absolute z-20 mt-1 max-h-56 w-full overflow-auto rounded-[10px] border border-border bg-card py-1 text-sm text-foreground shadow-lg">
64	      {shown.map((option, index) => <li key={option.code} id={`${id}-${index}`} role="option" aria-selected={index === active}
65	        className={`cursor-pointer px-3 py-2 hover:bg-muted ${index === active ? "bg-muted" : ""}`}
66	        onMouseDown={event => { event.preventDefault(); choose(option); }}>{option.label}</li>)}
67	    </ul>
68	    {!open && text.trim() && !known(code) && <span role="alert" className="mt-1 block text-xs text-danger">Not a supported currency. Search by name or code and choose from the list.</span>}
69	  </span>;
70	}
