// Lists (never prints emails of) disposable fixture users left behind since the given time. With --delete, removes them via delete_account().
import { createRequire } from "node:module";
import { pathToFileURL } from "node:url";
const require = createRequire(`${process.cwd()}/`);
process.loadEnvFile(".env");
const { default: postgres } = await import(pathToFileURL(require.resolve("postgres")).href);
const db = postgres(process.env.SUPABASE_DB_URL, { ssl: "require", max: 1 });
const since = process.argv[2];
const users = await db`select u.id, u.created_at, (select count(*)::int from public.transactions t join public.workspaces w on w.id=t.workspace_id where w.owner_id=u.id) transactions,
  (select count(*)::int from public.accounts a join public.workspaces w on w.id=a.workspace_id where w.owner_id=u.id) accounts
  from auth.users u where u.email like 'qa-%@example.invalid' and u.created_at >= ${since}::timestamptz order by u.created_at`;
const total = await db`select count(*)::int count from auth.users where email like 'qa-%@example.invalid'`;
console.log({ allDisposableFixtureUsers: total[0].count, sinceWindow: users.length });
for (const user of users) console.log(user.id, user.created_at.toISOString(), `transactions=${user.transactions}`, `accounts=${user.accounts}`);
if (process.argv.includes("--delete")) for (const user of users) {
  if (user.transactions || user.accounts) { console.log("skip, has data:", user.id); continue; }
  await db.begin(async tx => { await tx`select set_config('request.jwt.claim.sub',${user.id},true)`; await tx`select public.delete_account()`; });
  console.log("deleted", user.id);
}
await db.end();

// Prints the newest required acceptance result: failed unit tests and browser failures, with ANSI stripped.
import { existsSync, readFileSync, readdirSync } from "node:fs";
const root = ".qa", dir = `${root}/${readdirSync(root).filter(name => /^acceptance-required-\d+$/.test(name)).sort().at(-1)}`;
const result = JSON.parse(readFileSync(`${dir}/result.json`, "utf8"));
console.log(dir, { revision: result.revision.slice(0, 8), passed: result.passed, failure: result.failure, checks: result.checks, units: result.units, browser: result.browser });
const clean = text => String(text ?? "").replace(/\x1b\[[0-9;]*m/g, "").slice(0, 900);
if (existsSync(`${dir}/units.json`)) {
  const units = JSON.parse(readFileSync(`${dir}/units.json`, "utf8"));
  for (const file of units.testResults) for (const test of file.assertionResults) if (test.status === "failed") console.log("UNIT", file.name.split("t3-7d9fff38")[1], "::", test.fullName, "\n", clean(test.failureMessages[0]));
}
if (existsSync(`${dir}/browser.json`)) {
  const browser = JSON.parse(readFileSync(`${dir}/browser.json`, "utf8"));
  const walk = suite => {
    for (const child of suite.suites ?? []) walk(child);
    for (const spec of suite.specs ?? []) for (const test of spec.tests) {
      const last = test.results.at(-1);
      if (last && last.status !== "passed" && last.status !== "skipped") console.log("BROWSER", spec.file, "::", spec.title, last.status, "attempts", test.results.length, "\n", clean(last.error?.message));
      else if (test.results.length > 1) console.log("FLAKY", spec.file, "::", spec.title, "attempts", test.results.length);
    }
  };
  for (const suite of browser.suites) walk(suite);
  for (const error of browser.errors ?? []) console.log("GLOBAL", clean(error.message));
} else if (existsSync(`${dir}/browser.log`)) console.log(clean(readFileSync(`${dir}/browser.log`, "utf8").slice(-1500)));

