const state = process.env.E2E_STORAGE_STATE ?? (existsSync("e2e/.auth.json") ? "e2e/.auth.json" : undefined);
test("phone swipe", async ({ browser }) => {
  readFileSync(state!);
  const context = await browser.newContext({ storageState: state!, viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
  const page = await context.newPage();
  await page.goto("/", { waitUntil: "networkidle" });
  const cdp = await context.newCDPSession(page);
  const touch = async (type: "touchStart" | "touchMove" | "touchEnd", x = 0, y = 0) => { await cdp.send("Input.dispatchTouchEvent", { type, touchPoints: type === "touchEnd" ? [] : [{ x, y }] }); await page.waitForTimeout(20); };
  const swipe = async (label: string, stepPx: number, steps: number) => {
    await page.evaluate(() => scrollTo(0, 0));
    await page.waitForTimeout(200);
    const from = (await page.locator("[data-widget]:visible").first().boundingBox())!;
    const info = await page.evaluate(([x, y]) => { const e = document.elementFromPoint(x, y)!; return { scrollHeight: document.scrollingElement!.scrollHeight, inner: innerHeight, top: scrollY, at: e.tagName, cls: String(e.className).slice(0, 80), touchAction: getComputedStyle(e).touchAction, overflow: getComputedStyle(document.body).overflow, htmlOverflow: getComputedStyle(document.documentElement).overflow }; }, [from.x + 40, from.y + 30]);
    await touch("touchStart", from.x + 40, from.y + 30);
    for (let step = 1; step <= steps; step++) await touch("touchMove", from.x + 40, from.y + 30 - step * stepPx);
    await touch("touchEnd");
    await page.waitForTimeout(1500);
    console.log(label, JSON.stringify({ from: { x: from.x, y: from.y }, ...info, after: await page.evaluate(() => scrollY) }));
  };
  await swipe("not customizing 6x20", 20, 6);
  await swipe("not customizing 12x20", 20, 12);
  await page.getByRole("button", { name: "Customize", exact: true }).click();
  await swipe("customizing 6x20", 20, 6);
  await swipe("customizing 12x20", 20, 12);
  await context.close();
});

